package br.com.sistemacardapio.catalogo;
import java.math.BigDecimal;import java.util.UUID;import br.com.sistemacardapio.empresa.Empresa;import jakarta.persistence.*;
@Entity @Table(name="produto_variacao") public class ProdutoVariacao{
 @Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="empresa_id")private Empresa empresa;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="produto_id")private Produto produto;@Column(nullable=false,length=120)private String nome;@Column(nullable=false,precision=12,scale=2)private BigDecimal preco;@Column(nullable=false)private int ordem;@Column(nullable=false)private boolean ativa;protected ProdutoVariacao(){}public ProdutoVariacao(Produto p,String n,BigDecimal v,int o){id=UUID.randomUUID();empresa=p.getEmpresa();produto=p;atualizar(n,v,o,true);}public void atualizar(String n,BigDecimal v,int o,boolean a){nome=n.trim();preco=v;ordem=o;ativa=a;}public UUID getId(){return id;}public String getNome(){return nome;}public BigDecimal getPreco(){return preco;}public int getOrdem(){return ordem;}public boolean isAtiva(){return ativa;}}
